import math
import numpy as np

def gl_integrate(f, a, b, n):
    x, w = np.polynomial.legendre.leggauss(n)
    t = (b - a) / 2 * x + (a + b) / 2
    return float((b - a) / 2 * np.sum(w * f(t)))

def _parts(S0, K, r, sigma, T):
    m = (r - sigma ** 2 / 2) * T
    s = sigma * math.sqrt(T)
    zs = (math.log(K / S0) - m) / s
    ST = lambda z: S0 * np.exp(m + s * z)
    phi = lambda z: np.exp(-z ** 2 / 2) / math.sqrt(2 * math.pi)
    return zs, ST, phi

def gl_call_price(S0, K, r, sigma, T, n, zmax=8):
    zs, ST, phi = _parts(S0, K, r, sigma, T)
    return math.exp(-r * T) * gl_integrate(lambda z: (ST(z) - K) * phi(z), zs, zmax, n)

def gl_put_price(S0, K, r, sigma, T, n, zmax=8):
    zs, ST, phi = _parts(S0, K, r, sigma, T)
    return math.exp(-r * T) * gl_integrate(lambda z: (K - ST(z)) * phi(z), -zmax, zs, n)
